(() => {
  'use strict';
  const data=window.NEPAL_JOURNAL,region=document.body.dataset.journalRegion||'nepal';
  if(!data)return;
  const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const config=data.regions[region],photos=config.photos;
  let photoIndex=0,wordGroup='nepali',wordId='namaste',zoomed=false;
  const markup=`<dialog id="wordbook-dialog" class="journal-dialog" aria-labelledby="wordbook-title"><button class="close-dialog" data-journal-close aria-label="Close the wordbook">×</button><div class="wordbook-header"><div class="eyebrow">A LITTLE LANGUAGE. A CLOSER CONNECTION.</div><h2 id="wordbook-title">Words for<br><em>the journey.</em></h2><p>A greeting, a shared cup, a moment of peace. Discover a few Nepali expressions and Sanskrit reflections, with their meanings beside them.</p></div><div class="wordbook-tabs" role="tablist" aria-label="Wordbook languages"><button id="wordbook-nepali" role="tab" aria-selected="true" aria-controls="wordbook-panel" data-word-group="nepali">Everyday Nepali</button><button id="wordbook-sanskrit" role="tab" aria-selected="false" aria-controls="wordbook-panel" tabindex="-1" data-word-group="sanskrit">Sanskrit & shared roots</button></div><div id="wordbook-panel" class="wordbook-body" role="tabpanel" aria-labelledby="wordbook-nepali"><div id="wordbook-list" class="wordbook-list" aria-label="Choose a word"></div><article id="wordbook-detail" class="wordbook-detail"></article></div><p class="wordbook-footnote">Nepal is home to many languages and traditions. These are a few starting points. Roman spellings are reading aids; some Sanskrit-rooted words are also used in modern Nepali.</p></dialog><dialog id="journal-lightbox" class="journal-dialog journal-lightbox" aria-labelledby="journal-photo-title"><button class="close-dialog" data-journal-close aria-label="Close full photograph">×</button><div class="journal-lightbox-top"><div><p>THE PHOTOGRAPHIC FIELD JOURNAL</p><h2 id="journal-photo-title"></h2></div></div><div class="journal-photo-stage" tabindex="0" aria-label="Photograph. In full detail mode, scroll to explore the image."><img id="journal-full-image" alt=""></div><div class="journal-photo-controls"><span id="journal-photo-count"></span><div><button id="journal-photo-prev" aria-label="Previous journal photograph">←</button><button id="journal-photo-zoom" aria-pressed="false">View full detail</button><button id="journal-photo-next" aria-label="Next journal photograph">→</button></div></div><div id="journal-photo-credit" class="journal-photo-credit"></div></dialog>`;
  document.body.insertAdjacentHTML('beforeend',markup);
  function openDialog(dialog){$$('dialog[open]').forEach(d=>{if(d!==dialog)d.close();});if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
  $$('.journal-dialog').forEach(dialog=>{
    $('[data-journal-close]',dialog).addEventListener('click',()=>dialog.close());
    dialog.addEventListener('close',()=>{if(!$('dialog[open]'))document.body.classList.remove('modal-open');});
    dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
  });
  function renderWord(id){
    wordId=id;const w=data.phrases.find(w=>w.id===id);$$('[data-word]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.word===id));
    $('#wordbook-detail').innerHTML=`<span class="word-language">${escape(w.language)}</span><h3 lang="${w.lang}">${escape(w.script)}</h3><p class="word-roman">${escape(w.roman)}</p><h4>${escape(w.meaning)}</h4><p>${escape(w.note)}</p><div class="word-actions"><button id="copy-journal-word">Copy this phrase ↗</button><a href="${w.source}" target="_blank" rel="noopener">Language source ↗</a></div><div class="wordbook-feedback" id="wordbook-feedback" role="status"></div>`;
    $('#copy-journal-word').addEventListener('click',async()=>{const value=`${w.script} — ${w.roman} — ${w.meaning}`;try{await navigator.clipboard.writeText(value);$('#wordbook-feedback').textContent='Copied. A little Nepal to take with you.';}catch{const field=document.createElement('textarea');field.value=value;field.setAttribute('aria-hidden','true');field.style.cssText='position:fixed;left:0;top:0;opacity:0;width:1px;height:1px';$('#wordbook-detail').append(field);field.select();let copied=false;try{copied=document.execCommand('copy');}catch{}field.remove();$('#wordbook-feedback').textContent=copied?'Copied. A little Nepal to take with you.':'Select the phrase above to copy it in this browser.';}});
  }
  function renderWords(group){wordGroup=group;const list=data.phrases.filter(w=>(w.lang==='ne')===(group==='nepali'));$$('[data-word-group]').forEach(b=>{const yes=b.dataset.wordGroup===group;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});$('#wordbook-panel').setAttribute('aria-labelledby','wordbook-'+group);$('#wordbook-list').innerHTML=list.map(w=>`<button data-word="${w.id}" aria-pressed="false"><span lang="${w.lang}">${escape(w.script)}</span><small>${escape(w.meaning)}</small></button>`).join('');$$('[data-word]').forEach(b=>b.addEventListener('click',()=>renderWord(b.dataset.word)));renderWord(list[0].id);}
  $$('[data-word-group]').forEach((b,i,buttons)=>{b.addEventListener('click',()=>renderWords(b.dataset.wordGroup));b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?1:1-i;renderWords(buttons[next].dataset.wordGroup);buttons[next].focus();});});
  $$('[data-wordbook]').forEach(b=>b.addEventListener('click',()=>{renderWords(b.dataset.wordbook||'nepali');openDialog($('#wordbook-dialog'));}));
  function renderSpread(index){
    photoIndex=index;const p=photos[index];const wrap=$('#journal-spread');wrap.classList.toggle('is-panorama',p.width/p.height>2.4);
    wrap.innerHTML=`<button class="journal-image-button" id="open-journal-photo" aria-label="View ${escape(p.title)} full photograph"><img src="${p.src}" alt="${escape(p.alt)}" loading="lazy" width="${p.width}" height="${p.height}"><span class="journal-expand">VIEW THE PHOTOGRAPH ⤢</span></button><div class="journal-leaf"><span class="folio-number">${String(index+1).padStart(2,'0')}</span><span class="folio-overline">${escape(p.overline||'A PAGE FROM NEPAL')}</span><h3>${escape(p.displayTitle||p.title)}</h3><p>${escape(p.editorial||p.caption)}</p><div class="journal-location">${escape(p.location)}<span>REAL PHOTOGRAPHY · ${p.width.toLocaleString()} PX WIDE</span></div></div>`;
    $('#open-journal-photo').addEventListener('click',()=>openPhoto(index));
    $$('[data-journal-photo]').forEach(b=>{const yes=+b.dataset.journalPhoto===index;b.setAttribute('aria-selected',yes);b.tabIndex=yes?0:-1;});$('#journal-spread').setAttribute('aria-labelledby','journal-thumb-'+index);
  }
  function renderLightbox(){
    const p=photos[photoIndex],img=$('#journal-full-image');$('#journal-photo-title').textContent=p.title;img.src=p.src;img.alt=p.alt;img.style.setProperty('--native-width',p.width+'px');$('#journal-photo-count').textContent=String(photoIndex+1).padStart(2,'0')+' / '+String(photos.length).padStart(2,'0');
    $('#journal-photo-credit').innerHTML=`${escape(p.caption||p.location)}<small>Photo by ${escape(p.author)} · <a href="${p.source}" target="_blank" rel="noopener">Original source ↗</a> · <a href="${p.license_url}" target="_blank" rel="noopener">${escape(p.license)}</a> · ${p.width} × ${p.height} pixels. ${escape(p.changes||'Resized and recompressed for web display.')}</small>`;setZoom(false);
  }
  function setZoom(on){zoomed=on;$('.journal-photo-stage').classList.toggle('is-zoomed',on);$('#journal-photo-zoom').setAttribute('aria-pressed',on);$('#journal-photo-zoom').textContent=on?'Fit to screen':'View full detail';$('.journal-photo-stage').scrollTo(0,0);}
  function openPhoto(index){photoIndex=index;renderLightbox();openDialog($('#journal-lightbox'));}
  function stepPhoto(delta){photoIndex=(photoIndex+delta+photos.length)%photos.length;renderLightbox();renderSpread(photoIndex);}
  $('#journal-photo-prev').addEventListener('click',()=>stepPhoto(-1));$('#journal-photo-next').addEventListener('click',()=>stepPhoto(1));$('#journal-photo-zoom').addEventListener('click',()=>setZoom(!zoomed));$('#journal-lightbox').addEventListener('keydown',e=>{if(!zoomed&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();stepPhoto(e.key==='ArrowRight'?1:-1);}});
  const section=$('#field-journal');
  section.innerHTML=`<div class="journal-heading"><div><div class="eyebrow">${escape(config.label)}</div><span class="journal-script" lang="ne">सम्झना</span><h2>${config.heading}</h2></div><p>${escape(config.description)}</p></div><div id="journal-spread" class="journal-spread" role="tabpanel" aria-labelledby="journal-thumb-0"></div><div class="journal-thumbs" role="tablist" aria-label="Photographic journal scenes">${photos.map((p,i)=>`<button id="journal-thumb-${i}" role="tab" aria-selected="${i===0}" aria-controls="journal-spread" tabindex="${i===0?0:-1}" class="journal-thumb" data-journal-photo="${i}"><img src="${p.thumbnailSrc||p.src}" alt="" loading="lazy" width="400" height="250"><span><small>0${i+1}</small>${escape(p.shortTitle||p.title)}</span></button>`).join('')}</div><div class="journal-bottom"><p>Samjhana · Nepali for “memory.”<br>Original source colors. Every photograph has a place and a photographer.</p><button id="journal-credit-open">Photographer & image details ↗</button></div>`;
  $$('[data-journal-photo]').forEach((b,i,buttons)=>{b.addEventListener('click',()=>{renderSpread(i);if(innerWidth<600)$('#journal-spread').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?photos.length-1:(i+(e.key==='ArrowRight'?1:-1)+photos.length)%photos.length;renderSpread(n);buttons[n].focus();});});$('#journal-credit-open').addEventListener('click',()=>openPhoto(photoIndex));renderSpread(0);
  const video=$('#cinema-video')||$('#fw-video');
  if(video){
    const bar=document.createElement('div');bar.className='cinema-extra-controls';bar.innerHTML='<span class="cinema-capture-info">Real footage · original proportions</span><button type="button" aria-pressed="false" class="cinema-expand">Expand cinema ⤢</button>';video.insertAdjacentElement('afterend',bar);
    video.addEventListener('loadedmetadata',()=>{if(video.videoWidth)bar.querySelector('span').textContent=`${video.videoWidth} × ${video.videoHeight} · ${video.videoWidth>=1920?'Full HD capture':'Original capture'} · silent`;});
    const dialog=video.closest('dialog'),button=bar.querySelector('button');button.addEventListener('click',()=>{const expanded=dialog.classList.toggle('video-expanded');button.setAttribute('aria-pressed',expanded);button.textContent=expanded?'Standard view ↙':'Expand cinema ⤢';dialog.scrollTop=0;});dialog.addEventListener('close',()=>{dialog.classList.remove('video-expanded');button.setAttribute('aria-pressed',false);button.textContent='Expand cinema ⤢';});
  }
})();
